import { describe, expect, it, vi } from "vitest";
import { readFileSync } from "node:fs";
import type { JevClient } from "../jev-client.ts";
import { SEMANTIC_CORPUS, SEMANTIC_CORPUS_CATEGORIES, type SemanticCorpusFixture } from "../semantic-corpus.ts";
import { CORPUS_EVALUATION_ERROR, evaluateSemanticCorpus, isCorpusEvaluationPassing } from "../semantic-evaluator.ts";

function response(fixture: SemanticCorpusFixture) {
	const expected = fixture.expected;
	const p = (value: boolean) => ({ type: "noul", noul: value ? 0.95 : 0.05 });
	const states = ["working", "waiting_input", "waiting_approval", "presenting_result", "blocked", "other"];
	const probabilities = Object.fromEntries(states.map((state) => [state, state === expected.attention ? 0.95 : 0.01]));
	return {
		model: "jev-1.13.0", usage: { input_tokens: 10, output_tokens: 2 },
		answers: {
			requests_input: p(expected.requestsInput), requests_approval: p(expected.requestsApproval),
			presents_result: p(expected.presentsResult), requires_intervention: p(expected.requiresIntervention), meaningful_progress: p(expected.meaningfulProgress),
			attention: { type: "choice", choice: expected.attention, confidence: expected.route === "uncertain" ? 0.2 : 0.95, probabilities },
		},
	};
}

describe("repository semantic corpus", () => {
	it("is typed, uniquely identified, action-free, and covers every required category", () => {
		expect(new Set(SEMANTIC_CORPUS.map((fixture) => fixture.id)).size).toBe(SEMANTIC_CORPUS.length);
		expect(new Set(SEMANTIC_CORPUS.map((fixture) => fixture.category))).toEqual(new Set(SEMANTIC_CORPUS_CATEGORIES));
		for (const fixture of SEMANTIC_CORPUS) {
			expect(fixture.observation.actions).toEqual([]);
			expect(fixture.observation.session.lifecycle).toBe("running");
			expect(fixture.expected).toMatchObject({ attention: expect.any(String), route: expect.stringMatching(/^(continue|notify|uncertain)$/) });
			expect(JSON.stringify(fixture.expected)).not.toMatch(/probability|confidence/i);
		}
		expect(JSON.stringify(SEMANTIC_CORPUS.find((item) => item.category === "secret-prompt"))).not.toMatch(/hunter|actual-secret|sk-/i);
	});

	it("uses only a fake JevClient seam and aggregates deterministic predictions", async () => {
		const evaluatorSource = readFileSync("semantic-evaluator.ts", "utf-8");
		expect(evaluatorSource).not.toContain("createJevClient");
		expect(evaluatorSource).not.toContain("TYPESAFE_API_KEY");
		const requests: any[] = [];
		const byRecent = new Map(SEMANTIC_CORPUS.map((fixture) => [fixture.observation.terminal.recentOutput, fixture]));
		const client: JevClient = { evaluate: vi.fn(async (request) => {
			requests.push(request);
			const observation = (request.state as any).observation;
			const fixture = byRecent.get(observation.terminal.recentOutput)!;
			return response(fixture);
		}) };
		let now = 0;
		const clock = vi.spyOn(Date, "now").mockImplementation(() => { now += 10; return now; });
		const report = await evaluateSemanticCorpus({ client, model: "jev-1.13.0", requestTimeoutMs: 10_000 });
		clock.mockRestore();
		expect(client.evaluate).toHaveBeenCalledTimes(SEMANTIC_CORPUS.length - 1);
		expect(report).toMatchObject({ fixtureCount: 10, evaluatedCount: 9, correctCount: 9, accuracy: 1, uncertaintyCount: 1, errorCount: 0, secretSkippedCount: 1 });
		expect(report.inputTokens).toEqual({ total: 90, average: 10, samples: 9 });
		expect(report.latency).toEqual({ totalMs: 90, averageMs: 10, maxMs: 10, samples: 9 });
		expect(Object.values(report.confusion).reduce((a, b) => a + b, 0)).toBe(9);
		expect(isCorpusEvaluationPassing(report)).toBe(true);
		for (const request of requests) {
			expect((request.state as any).observation.actions).toEqual([]);
			expect(request.questions).not.toHaveProperty("action");
			expect(Object.keys(request.questions).some((key) => key.startsWith("action_ready:"))).toBe(false);
		}
	});

	it("records fixed errors for malformed responses and request failures, then continues", async () => {
		const fixtures = SEMANTIC_CORPUS.filter((fixture) => !fixture.expected.secretPrompt).slice(0, 3);
		let call = 0;
		const client: JevClient = { evaluate: vi.fn(async () => {
			call += 1;
			if (call === 1) return { provider_body: "must-not-leak" };
			if (call === 2) throw new Error("provider body must-not-leak");
			return response(fixtures[2]!);
		}) };
		const report = await evaluateSemanticCorpus({ client, model: "jev-1.13.0", requestTimeoutMs: 999_999, fixtures });
		expect(report.errorCount).toBe(2);
		expect(report).toMatchObject({ evaluatedCount: 1, correctCount: 1, accuracy: 1, secretSkippedCount: 0 });
		expect(isCorpusEvaluationPassing(report)).toBe(false);
		expect(report.latency.samples).toBe(3);
		expect(report.predictions.map((item) => item.status)).toEqual(["error", "error", "evaluated"]);
		expect(report.predictions[0]?.error).toBe(CORPUS_EVALUATION_ERROR);
		expect(JSON.stringify(report)).not.toContain("must-not-leak");
		expect((client.evaluate as any).mock.calls.every((callArgs: any[]) => callArgs[1].timeoutMs === 30_000)).toBe(true);
	});

	it("gates on the user-visible outcome while retaining atomic accuracy as a diagnostic", async () => {
		const fixture = SEMANTIC_CORPUS.find((item) => item.id === "yes-no-confirmation")!;
		const raw = response(fixture);
		raw.answers.requests_input = { type: "noul", noul: 0.95 };
		const client: JevClient = { evaluate: vi.fn(async () => raw) };
		const report = await evaluateSemanticCorpus({ client, model: "jev-1.13.0", requestTimeoutMs: 10_000, fixtures: [fixture] });
		expect(report).toMatchObject({ correctCount: 1, accuracy: 1, atomicCorrectCount: 0, atomicAccuracy: 0 });
		expect(report.predictions[0]).toMatchObject({ correct: true, atomicCorrect: false, route: "notify" });
		expect(isCorpusEvaluationPassing(report)).toBe(true);
	});
});

import { describe, expect, it, vi } from "vitest";
import { buildOutputSelectionInput, normalizeSelectorVisibleText, runOutputSelection } from "../output-selection-runtime.ts";
import type { JevClient } from "../jev-client.ts";

function answersFor(request: any, keepPositions = new Set<number>()): unknown {
	const answers: Record<string, unknown> = {};
	for (let index = 0; index < request.state.blocks.length; index++) {
		const keep = keepPositions.has(request.state.blocks[index].position);
		for (const kind of ["problem_or_failure", "substantive_result", "artifact_or_report_location", "explicit_goal_evidence", "routine_progress"]) {
			answers[`b${index}_${kind}`] = { type: "noul", noul: kind === "routine_progress" ? 1 : keep ? 1 : 0 };
		}
	}
	return { answers, model: "jev-1.13.0", usage: { input_tokens: 10, output_tokens: 5 } };
}

describe("output selection runtime adapter", () => {
	it("bypasses a boundary-spanning auth canary before any provider call", async () => {
		const evaluate = vi.fn(async () => { throw new Error("must not call"); });
		const raw = `${"routine output\n".repeat(500)}api_\nkey=boundary-canary\n`;
		const result = await runOutputSelection({ sourceId: "source", raw, metadata: { goal: "summarize", command: "job" }, redactionPatterns: [], client: { evaluate } });
		expect(evaluate).not.toHaveBeenCalled();
		expect(result.status).toBe("pagination-required");
		expect("reason" in result && result.reason).toBe("secret-like-input");
	});

	it("does not count ANSI/CR transport characters as visible output and preserves exact raw mapping", async () => {
		const evaluate = vi.fn();
		const raw = `${"\x1b[31m".repeat(1000)}ok\rnext\x1b[0m`;
		const built = buildOutputSelectionInput("source", raw, { goal: "summarize", command: "job" }, []);
		expect(built.input.source.visibleLength).toBeLessThan(20);
		const result = await runOutputSelection({ sourceId: "source", raw, metadata: { goal: "summarize", command: "job" }, redactionPatterns: [], client: { evaluate } as JevClient });
		expect(evaluate).not.toHaveBeenCalled();
		expect(result.status).toBe("unchanged");
		expect(result.excerpts[0]?.range).toEqual({ start: 0, end: raw.length });
		expect(result.text).toBe("next");
		expect(result.text).not.toContain("\x1b");
		expect(raw.slice(result.excerpts[0]!.range.start, result.excerpts[0]!.range.end)).toBe(raw);
	});

	it("applies terminal-style CR overwrite while retaining shorter-overwrite trailing cells", () => {
		expect(normalizeSelectorVisibleText("progress 99%\rprogress 100%" )).toBe("progress 100%");
		expect(normalizeSelectorVisibleText("abcdef\rxy")).toBe("xycdef");
		expect(normalizeSelectorVisibleText("\x1b[31mabcdef\x1b[0m\rxy")).toBe("xycdef");
	});

	it("bypasses an overwritten raw secret before provider construction", async () => {
		const evaluate = vi.fn(async () => { throw new Error("must not call"); });
		const raw = `${"routine output\n".repeat(500)}password=hidden-canary\rstatus=clear\n`;
		const result = await runOutputSelection({ sourceId: "source", raw, metadata: { goal: "summarize", command: "job" }, redactionPatterns: [], client: { evaluate } });
		expect(evaluate).not.toHaveBeenCalled();
		expect("reason" in result && result.reason).toBe("secret-like-input");
		expect(result.rawSourceReference.ranges).toEqual([{ start: 0, end: raw.length }]);
	});

	it("uses final CR-overwritten cells in provider model state", async () => {
		const requests: any[] = [];
		const client: JevClient = { evaluate: vi.fn(async (request) => { requests.push(request); return answersFor(request); }) };
		const raw = Array.from({ length: 24 }, (_, index) => `progress ${index}%\rprogress 100% ${"x".repeat(230)}\n`).join("");
		await runOutputSelection({ sourceId: "source", raw, metadata: { goal: "summarize", command: "job" }, redactionPatterns: [], client });
		expect(requests.length).toBeGreaterThan(0);
		const state = JSON.stringify(requests.map((request) => request.state));
		expect(state).not.toContain("progress 0%");
		expect(state).not.toContain("\\r");
		expect(state).not.toContain("\\u001b");
		expect(state).toContain("progress 100%");
	});

	it("sends only normalized redacted bounded state and returns recoverable raw ranges", async () => {
		const requests: any[] = [];
		const client: JevClient = { evaluate: vi.fn(async (request) => { requests.push(request); return answersFor(request, new Set([0, 12])); }) };
		const raw = Array.from({ length: 24 }, (_, index) => `line ${index} ${"x".repeat(240)}\n`).join("");
		const result = await runOutputSelection({ sourceId: "source", raw, metadata: { goal: "summarize CANARY", command: "run CANARY" }, redactionPatterns: ["CANARY"], client });
		expect(result.status).toBe("selected");
		expect(requests.length).toBeGreaterThan(0);
		const serialized = JSON.stringify(requests);
		expect(serialized).not.toContain("CANARY");
		expect(serialized).toContain("[REDACTED]");
		expect(requests.every((request) => Buffer.byteLength(JSON.stringify(request)) < 48 * 1024)).toBe(true);
		expect(result.rawSourceReference.ranges).toEqual([{ start: 0, end: raw.length }]);
		for (const excerpt of result.excerpts) expect(raw.slice(excerpt.range.start, excerpt.range.end)).toBeTruthy();
	});
});

